insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-BIO-L1', 'Unit 1 The heart, blood and lungs: Your heart, blood and lungs', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["True", "True", "True", "False"], "tip": "Think about where your heart is."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Artery", "Vein", "Capillary"], "tip": "A for away."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Oxygen", "Carbon dioxide", "Carbon dioxide", "Oxygen"], "tip": "In or out?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["windpipe", "trachea"], ["lungs", "air sacs", "blood"]], "tips": ["Nose → … → blood."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["muscles", "more oxygen", "oxygen"], ["faster", "pump", "more blood", "quickly"]], "tips": ["What do muscles need?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["rest", "before", "sitting"], ["exercise", "jump", "run", "one minute"], ["count", "measure", "pulse", "after", "compare", "repeat"]], "tips": ["Before, during, after."]}]}, "models": {"1": [["Q1", "True; true; true; false (it is in your chest)."]], "2": [["Q2", "Artery; vein; capillary."]], "3": [["Q3", "Oxygen; carbon dioxide; carbon dioxide; oxygen."], ["Q4", "Air goes down the windpipe [1] into the lungs, where oxygen passes into the blood [1]."]], "4": [["Q5", "Your muscles need more oxygen [1], so the heart pumps blood faster to carry it to them [1]."]], "5": [["Q6", "Count your pulse for one minute at rest [1]; do one minute of exercise such as star jumps [1]; count your pulse again straight after and compare (repeat to check) [1]."], ["Q7", "The more energetic the exercise, the higher the pulse rate."]], "6": [["Exit ticket", "Arteries."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q5_1": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false?", "Q2": "Which blood vessel?", "Q3": "Oxygen or carbon dioxide?", "Q4": "Describe the path of air from your nose to your blood.", "Q5": "Explain why your heart beats faster when you run.", "Q6": "Plan an investigation to find out how exercise affects your pulse rate.", "Q7": "In your book, draw a bar chart of a pulse rate at rest, after walking and after running. Write one sentence about the pattern."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
