insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-BIO-L2', 'Unit 2 Human reproduction and puberty: Growing up: reproduction and puberty', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["1st", "2nd", "3rd", "4th"], "tip": "Youngest to oldest."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Ovary", "Uterus", "Testis"], "tip": "Match the job."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Both", "Boys", "Girls", "Both", "Boys"], "tip": "Some changes happen to everyone."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["sweat", "oil", "glands"], ["smell", "odour", "bacteria", "spots", "clean"]], "tips": ["What increases?"]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 1, "pts": [["yes", "normal", "different ages", "different times"]], "tips": ["When does it start?"]}]}, "models": {"1": [["Q1", "Baby, child, adolescent, adult."]], "2": [["Q2", "Ovary; uterus; testis."]], "3": [["Q3", "Both; boys; girls; both; boys."]], "4": [["Q4", "Sweat and oil glands become more active [1], so washing stops body odour and spots [1]."], ["Q5", "Yes: puberty starts at different ages for different people [1]."]], "5": [["Q6", "e.g. growth spurt, body hair, voice changes; wash daily, sleep well, talk to a trusted adult."]], "6": [["Exit ticket", "Hormones (chemical messengers)."]]}, "labels": {"q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Put the human life cycle stages in order.", "Q2": "Which part?", "Q3": "Happens to girls, boys or both?", "Q4": "Explain why washing every day becomes more important during puberty.", "Q5": "Two friends are both 11. One has started puberty and one has not. Is this normal? Explain.", "Q6": "In your book, design a short leaflet for younger pupils called \"Growing up is normal\". Include three changes during puberty and three tips for looking after yourself."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
