insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-BIO-L3', 'Unit 3 Microorganisms, disease and defence: Germs, disease and our defences', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Useful", "Harmful", "Useful", "Harmful"], "tip": "Not all microbes are bad."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Insect bites", "Water", "Air", "Touch"], "tip": "Think of the route."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Malaria", "Cholera", "Colds and flu", "Malaria"], "tip": "Match the route."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["germ", "microorganism", "bacteria", "removes"], ["mouth", "food", "swallow", "body", "spread"]], "tips": ["Hands → food → mouth."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 3, "n": 3, "ans": ["Stomach acid", "Mucus", "Skin"], "tip": "Where is it?"}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["skin", "barrier", "broken", "opening"], ["germ", "infection", "bacteria"]], "tips": ["The barrier is broken."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["net", "mosquito net"], ["standing water", "drain", "empty", "repellent", "spray", "long sleeves"], ["bite", "mosquito", "breed", "carry"]], "tips": ["Stop the mosquitoes."]}]}, "models": {"1": [["Q1", "Useful; harmful; useful; harmful."]], "2": [["Q2", "Insect bites; water; air; touch."]], "3": [["Q3", "Malaria; cholera; colds and flu; malaria."], ["Q4", "Soap removes germs from your hands [1], so they do not get onto your food and into your body [1]."]], "4": [["Q5", "Stomach acid; mucus; skin."], ["Q6", "The skin barrier is broken [1], so germs could get in and cause an infection [1]."]], "5": [["Q7", "Sleep under treated nets [1]; empty standing water / use repellent [1]; this stops mosquitoes breeding or biting, so they cannot pass on malaria [1]."]], "6": [["Exit ticket", "Skin / mucus / stomach acid."]]}, "labels": {"q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Harmful or useful?", "Q2": "How does it spread?", "Q3": "Which disease does it help prevent most?", "Q4": "Explain why washing your hands with soap before eating helps stop disease.", "Q5": "Which defence?", "Q6": "Explain why a cut should be cleaned and covered.", "Q7": "A village has many cases of malaria. Suggest three actions to reduce malaria and explain one of them."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
