insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-BIO-L4', 'Unit 4 Food chains, food webs and toxins: Energy, food webs and toxins', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Producer", "Consumer", "Producer", "Consumer"], "tip": "Who makes their own food?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["energy", "less energy"], ["used", "lost", "moving", "living", "each step"]], "tips": ["Energy at each step."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Algae", "Heron", "Fish", "Tadpole"], "tip": "Follow the arrows."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["algae → tadpole → dragonfly larva → fish → heron", "algae tadpole dragonfly", "dragonfly"]], "tips": ["Five links."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["plant", "seed", "crop", "absorb"], ["mice eat", "eaten", "pass"], ["build up", "many mice", "more", "accumulate"]], "tips": ["Follow the chain."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["small fish", "algae", "eat", "pass"], ["build up", "large fish", "top", "more"], ["stop", "clean", "treat", "law", "filter", "eat less"]], "tips": ["Build-up plus action."]}]}, "models": {"1": [["Q1", "Maize and seaweed are producers; goat and eagle are consumers."]], "2": [["Q2", "Less energy reaches the cheetahs [1] because gazelles use most of their energy for moving and living [1]."]], "3": [["Q3", "Algae; heron; fish; tadpole."], ["Q4", "algae → tadpole → dragonfly larva → fish → heron [1]."]], "4": [["Q5", "The crops take in the pesticide [1]; mice eat the crops and the toxin passes to them [1]; each eagle eats many mice, so the toxin builds up in its body [1]."]], "5": [["Q6", "Mercury passes from small organisms to small fish to large fish [1]; it builds up so large fish contain the most, which people then eat [1]; the factory should be stopped from releasing mercury / people should eat fewer large fish [1]."]], "6": [["Exit ticket", "The Sun."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Producer or consumer?", "Q2": "Explain why there are fewer cheetahs than gazelles in an area.", "Q3": "Use the pond web above.", "Q4": "Write the longest food chain from the pond web.", "Q5": "A pesticide is sprayed on a field. Explain why eagles that eat mice from the field can be harmed even though they were never sprayed.", "Q6": "A factory releases mercury into Lake Victoria. Explain why people who eat lots of large fish could be at risk, and suggest one solution."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
