insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-CHEM-L1', 'Unit 1 Properties of materials: Melting points, gases and conductors', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Solid", "Liquid", "Gas", "Solid"], "tip": "Compare with 25 °C."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["empty", "deflated", "weigh first", "before"], ["blow", "inflate", "heavier", "more mass", "after"]], "tips": ["Compare before and after."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Conductor", "Insulator", "Insulator", "Conductor"], "tip": "Metals conduct."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["circuit", "gap", "cell", "bulb"], ["lights", "bulb lights", "conduct"]], "tips": ["Use a circuit with a gap."]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["copper+conduct"], ["plastic+insulat", "safe", "shock"]], "tips": ["Two jobs."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["wrap", "different material", "wool", "foil", "paper"], ["same", "volume", "starting temperature", "cup"], ["thermometer", "measure", "temperature", "minutes", "time"]], "tips": ["One variable."]}]}, "models": {"1": [["Q1", "Solid; liquid; gas; solid."]], "2": [["Q2", "Weigh the empty balloon [1]; blow it up and weigh it again: it is heavier, so air has mass [1]."]], "3": [["Q3", "Conductor; insulator; insulator; conductor."]], "4": [["Q4", "Place the coin in the gap of a circuit with a cell and a bulb [1]; if the bulb lights, the coin conducts [1]."], ["Q5", "Copper conducts electricity [1]; plastic is an insulator that stops electric shocks [1]."]], "5": [["Q6", "Wrap identical cups in different materials [1]; use the same volume of water at the same starting temperature [1]; measure the temperature with a thermometer every 5 minutes and compare [1]."]], "6": [["Exit ticket", "100 °C."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Solid, liquid or gas at room temperature (25 °C)?", "Q2": "Describe how you could show that air has mass using a balloon and a balance.", "Q3": "Thermal conductor or insulator?", "Q4": "Describe how to test whether a coin conducts electricity.", "Q5": "Explain why electric cables are made of copper covered in plastic.", "Q6": "Plan a test to find which material keeps a cup of hot water warm for longest."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
