insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-CHEM-L2', 'Unit 2 Dissolving, boiling and evaporation: Where does the sugar go?', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Reversible", "Not reversible", "Reversible", "Not reversible"], "tip": "Can you get it back?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Soluble", "Insoluble", "Soluble", "Insoluble"], "tip": "Does it disappear?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["220"], ["not lost", "still there", "particles", "conserved"]], "tips": ["Is anything lost?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["temperature", "different", "cold", "warm", "hot"], ["same volume", "same amount of water", "stir", "same"], ["count", "spoons", "until", "no more", "mass"]], "tips": ["Change one thing."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Evaporation", "Boiling", "Evaporation", "Boiling"], "tip": "Bubbles and temperature."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["surface", "throughout", "all through", "bubbles"], ["any temperature", "boiling point", "100"]], "tips": ["Where and when."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["evaporat"], ["salt left", "left behind", "crystals"], ["hot", "wind", "faster"]], "tips": ["Reverse dissolving."]}]}, "models": {"1": [["Q1", "Reversible; not; reversible; not."]], "2": [["Q2", "Salt and sugar dissolve; sand and chalk do not."], ["Q3", "220 g [1] because the salt particles are still there, just spread out [1]."]], "3": [["Q4", "Use water at different temperatures [1]; keep the volume of water and the stirring the same [1]; add sugar a spoonful at a time and count how many dissolve before no more will [1]."]], "4": [["Q5", "Evaporation; boiling; evaporation; boiling."], ["Q6", "Evaporation happens only at the surface, boiling all through the liquid [1]; evaporation happens at any temperature, boiling only at the boiling point [1]."]], "5": [["Q7", "The water evaporates [1] and the salt is left behind as crystals [1]; hot sun and wind make evaporation faster [1]."]], "6": [["Exit ticket", "A solute dissolved in a solvent."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Reversible or not?", "Q2": "Soluble or insoluble in water?", "Q3": "20 g of salt dissolves in 200 g of water. What is the mass of the solution? Explain.", "Q4": "Plan a fair test to find whether temperature affects how much sugar dissolves.", "Q5": "Boiling or evaporation?", "Q6": "Give two differences between boiling and evaporation.", "Q7": "Explain how people at a salt pan get salt from sea water and why it works best in hot, windy places."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
