insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-CHEM-L3', 'Unit 3 Chemical reactions: Making new materials: chemical reactions', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Reactant", "Product", "Reactant", "Product"], "tip": "Before or after?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Gas given off", "Colour change", "Temperature change", "Colour change"], "tip": "What do you observe?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Physical change", "Chemical reaction", "Physical change", "Chemical reaction", "Chemical reaction"], "tip": "New material?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["gas", "bubbles"], ["new", "cannot", "irreversible", "not reversible", "cannot change back"]], "tips": ["Gas and new material."]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["oil", "grease", "paint"], ["water", "air", "oxygen", "keep out"]], "tips": ["What does rust need?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["different amount", "teaspoon", "amount of baking soda"], ["same", "vinegar", "volume", "bottle"], ["balloon", "measure", "size", "height", "foam"]], "tips": ["Measure the gas."]}]}, "models": {"1": [["Q1", "Reactant; product; reactant; product."]], "2": [["Q2", "Gas; colour; temperature; colour."]], "3": [["Q3", "Physical; chemical; physical; chemical; chemical."]], "4": [["Q4", "Gas bubbles are made [1] and the cake cannot be turned back into the ingredients, so new materials have formed [1]."], ["Q5", "Oil the chain [1]; it keeps water and oxygen away from the iron [1]."]], "5": [["Q6", "Use different amounts of baking soda [1]; keep the volume of vinegar and the container the same [1]; put a balloon over the bottle and measure how big it gets [1]."]], "6": [["Exit ticket", "Fizzing / colour change / temperature change."]]}, "labels": {"q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Reactant or product?", "Q2": "Which sign?", "Q3": "Chemical reaction or physical change?", "Q4": "A cake rises in the oven. Explain why this is a chemical reaction.", "Q5": "Suggest one way to stop a bicycle chain rusting and explain how it works.", "Q6": "Plan an investigation to find out whether the amount of baking soda affects how much gas is made with vinegar."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
