insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-CHEM-L4', 'Unit 4 Rocks, soils and fossils (Earth and Space): How rocks, fossils and soils form', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Igneous", "Sedimentary", "Metamorphic", "Igneous"], "tip": "How did it form?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1st", "2nd", "3rd", "4th"], "tip": "Death to fossil."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["sediment", "mud", "layers", "buried"], ["igneous+hot", "magma", "melt", "destroyed", "burnt"]], "tips": ["How each forms."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Sandy", "Clay", "Loam"], "tip": "Particle size."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["compost", "manure", "humus", "organic"], ["hold water", "nutrients", "keep water"]], "tips": ["Add something."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["weather", "break"], ["erode", "carried", "river", "transport"], ["layer", "deposit", "pressed", "settle"]], "tips": ["Break, move, settle."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["funnel", "filter", "same amount of soil", "soil"], ["same volume", "same water", "same"], ["time", "measure", "collected", "cylinder"]], "tips": ["Same water, measure time."]}]}, "models": {"1": [["Q1", "Igneous; sedimentary; metamorphic; igneous."]], "2": [["Q2", "Buried; soft parts rot; layers become rock; minerals replace bones."], ["Q3", "Sedimentary rock forms from layers of mud that bury dead organisms [1]; igneous rock forms from hot magma which would destroy any remains [1]."]], "3": [["Q4", "Sandy; clay; loam."], ["Q5", "Add compost or manure (humus) [1], which holds water and adds nutrients [1]."]], "4": [["Q6", "The igneous rock is weathered into small pieces [1]; the pieces are carried away by rivers (erosion) [1]; they settle in layers and are pressed together into sedimentary rock [1]."]], "5": [["Q7", "Put the same mass of each soil in a funnel lined with filter paper [1]; pour the same volume of water onto each [1]; measure how much water drains through in 5 minutes [1]."]], "6": [["Exit ticket", "Igneous."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which type of rock?", "Q2": "Put the fossil steps in order.", "Q3": "Explain why fossils are found in sedimentary rock but not in igneous rock.", "Q4": "Which soil?", "Q5": "A farmer has sandy soil that dries out quickly. Suggest how she could improve it and explain.", "Q6": "Describe how an igneous rock can become a sedimentary rock.", "Q7": "Plan an investigation to compare how quickly water drains through sandy soil and clay soil."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
