insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-PHYS-L1', 'Unit 1 Mass, weight and forces: Pushes, pulls and weight', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Mass", "Weight", "Weight", "Mass"], "tip": "kg or N?"}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 1, "pts": [["30"]], "tips": ["1 kg ≈ 10 N."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["60 kg", "60"], ["100"]], "tips": ["Mass stays; weight ÷ 6."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Down", "Against the motion", "Up", "Against the motion"], "tip": "Direction."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Balanced", "Unbalanced", "Balanced", "Unbalanced"], "tip": "Is the motion changing?"}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["left"], ["100", "unbalanced"]], "tips": ["Find the difference."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["force meter", "attach", "hook"], ["pull", "steady", "slowly", "same"], ["read", "newton", "compare", "record"]], "tips": ["Pull and read."]}]}, "models": {"1": [["Q1", "Mass; weight; weight; mass."], ["Q2", "30 N [1]."]], "2": [["Q3", "Mass 60 kg [1]; weight about 100 N [1]."]], "3": [["Q4", "Down; against motion; up; against motion."]], "4": [["Q5", "Balanced; unbalanced; balanced; unbalanced."], ["Q6", "The rope moves to the left [1] because the forces are unbalanced by 100 N [1]."]], "5": [["Q7", "Hook the force meter to the shoe [1]; pull it steadily along each surface [1]; read the force in newtons and compare: the bigger reading means more friction [1]."]], "6": [["Exit ticket", "Newtons (N)."]]}, "labels": {"q1_1": "Q2", "q2_0": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Mass or weight?", "Q2": "A bag has a mass of 3 kg. What is its weight on Earth?", "Q3": "An astronaut has a mass of 60 kg. Her weight on Earth is 600 N. What are her mass and weight on the Moon?", "Q4": "Which way does the force act?", "Q5": "Balanced or unbalanced?", "Q6": "A team pulls with 500 N to the left and the other with 400 N to the right. What happens?", "Q7": "Describe how to use a force meter to compare the friction of a shoe on carpet and on a tiled floor."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
