insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-PHYS-L2', 'Unit 2 Floating and sinking: Why things float or sink', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Float", "Sink", "Float", "Sink"], "tip": "Compare forces."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["wide", "shape", "spread", "hollow"], ["more water", "more upthrust", "displace", "pushes aside"]], "tips": ["Same mass, different shape."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["lower", "sinks", "deeper"], ["weight", "heavier", "more than upthrust"]], "tips": ["Weight increases."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Float", "Sink", "Float", "Float"], "tip": "Shape and material."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["different shape", "shapes"], ["same size", "same foil", "same mass", "same piece"], ["count", "marbles", "until", "sink"]], "tips": ["One variable."]}]}, "models": {"1": [["Q1", "Float; sink; float; sink."]], "2": [["Q2", "The boat shape is wide and hollow [1], so it pushes aside more water and gets more upthrust [1]."]], "3": [["Q3", "The boat sits lower and lower until it sinks [1] because its weight becomes bigger than the upthrust [1]."]], "4": [["Q4", "Float; sink; float; float."]], "5": [["Q5", "Make boats of different shapes [1] from the same size piece of foil [1]; add marbles one at a time and count how many each holds before sinking [1]."]], "6": [["Exit ticket", "Upthrust."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Float or sink?", "Q2": "Explain why a plasticine boat floats but the same plasticine as a ball sinks.", "Q3": "A student adds marbles one at a time to a foil boat. Predict what happens and explain.", "Q4": "Will it float?", "Q5": "Plan a fair test to find which foil boat shape holds the most marbles before sinking."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
