insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-PHYS-L4', 'Unit 4 Series and parallel circuits: One path or many?', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Cell", "Lamp", "Switch", "Buzzer"], "tip": "Standard symbols."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Lamps get dimmer", "All lamps go out", "Lamps get brighter"], "tip": "One path."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["stays on", "stays lit", "still on", "keeps working"], ["own", "branch", "separate path", "complete"]], "tips": ["Separate paths."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Dimmer", "The same", "Brighter"], "tip": "Series shares; parallel does not."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["one breaks", "others stay on", "independent"], ["own switch", "switch separately", "bright", "full"]], "tips": ["Think about using lights."]}], "5": [{"kind": "text", "id": "q5_1", "q": "Q7", "max": 2, "pts": [["series", "one loop", "one path"], ["broken", "gap", "not complete", "no current"]], "tips": ["One path."]}]}, "models": {"1": [["Q1", "Cell; lamp; switch; buzzer."]], "2": [["Q2", "Dimmer; all go out; brighter."]], "3": [["Q3", "It stays on [1] because it is on its own branch, which is still a complete circuit [1]."]], "4": [["Q4", "Dimmer; the same; brighter."], ["Q5", "If one bulb breaks the others stay on [1]; each light can be switched on and off separately / stays fully bright [1]."]], "5": [["Q6", "A parallel circuit with one lamp and one switch on each branch."], ["Q7", "They are in series, so there is only one path [1]; the broken bulb makes a gap, so no current flows to any bulb [1]."]], "6": [["Exit ticket", "Parallel."]]}, "labels": {"q3_0": "Q3", "q4_1": "Q5", "q5_0": "Q6", "q5_1": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the symbol.", "Q2": "Series circuit: what happens?", "Q3": "Two lamps are in parallel. One breaks. What happens to the other? Explain.", "Q4": "Brighter, dimmer or the same as one lamp alone?", "Q5": "Give two reasons why houses are wired in parallel.", "Q6": "In your book, draw a circuit for a doll''s house with two rooms, so that each room''s lamp has its own switch.", "Q7": "Explain why fairy lights wired in series all go out when one bulb breaks."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
