insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-PHYS-L5', 'Unit 5 The Sun, Earth and Moon (Earth and Space): Our place in space: the Sun, Earth and Moon', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Mercury", "Earth", "Jupiter", "Neptune"], "tip": "Use the mnemonic."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["24 hours", "About 28 days", "About 365 days"], "tip": "Day, month, year."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["reflect"], ["sun", "sunlight"]], "tips": ["Where does the light come from?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["New moon", "Full moon", "Crescent", "Half moon"], "tip": "How much is lit?"}], "5": [{"kind": "text", "id": "q5_1", "q": "Q6", "max": 3, "pts": [["lamp", "sun"], ["ball", "moon", "hold"], ["turn", "around", "circle", "spin", "orbit"]], "tips": ["Lamp = Sun, ball = Moon, head = Earth."]}]}, "models": {"1": [["Q1", "Mercury; Earth; Jupiter; Neptune."]], "2": [["Q2", "24 hours; 28 days; 365 days."]], "3": [["Q3", "The Moon reflects [1] light from the Sun into our eyes [1]."]], "4": [["Q4", "New; full; crescent; half."]], "5": [["Q5", "Drawings should show the lit part growing (waxing) or shrinking (waning)."], ["Q6", "The lamp is the Sun [1]; hold the ball (Moon) at arm''s length [1]; turn slowly in a circle and watch how much of the lit side you can see [1]."]], "6": [["Exit ticket", "About 28 days (a month)."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q5_1": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which planet?", "Q2": "How long does it take?", "Q3": "Explain why we can see the Moon even though it does not make its own light.", "Q4": "Which phase?", "Q5": "Over the next two weeks, draw the shape of the Moon each clear night in your book. Label each drawing with the date and the phase.", "Q6": "Describe how to model the phases of the Moon using a lamp, a ball and your head."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
