insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L1', 'Unit 1 Counting and sequences: Counting patterns and sequences', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["4", "−5", "1¼", "0.9"], "tip": "Find the step."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["7"], ["any", "0", "1", "2", "3", "4", "6", "8", "9", "10", "11", "12"]], "tips": ["They must add to 12."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["40", "35", "60", "18"], "tip": "Multiply the position."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["36, 49, 64", "36 49 64"], ["6 × 6", "multiply", "itself", "squared"]], "tips": ["Number times itself."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["3 ×", "times 3", "3 times"], ["60"]], "tips": ["Position-to-term."]}]}, "models": {"1": [["Q1", "4; −5; 1¼; 0.9."]], "2": [["Q2", "b = 7 [1]; any other pair adding to 12, e.g. a = 4, b = 8 [1]."]], "3": [["Q3", "40; 35; 60; 18."]], "4": [["Q4", "36, 49, 64 [1]; 6 × 6, 7 × 7, 8 × 8 [1]."]], "5": [["Q5", "Each term is 3 × position [1]; 3 × 20 = 60 [1]."]], "6": [["Exit ticket", "36."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Next term?", "Q2": "a + b = 12 and a is 5. Find b. Then give another pair of values for a and b.", "Q3": "Find the term.", "Q4": "Write the next three square numbers after 25 and explain how you found them.", "Q5": "A pattern of triangles uses 3, 6, 9, 12 … matchsticks. How many for the 20th pattern? Explain."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
