insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L2', 'Unit 2 Integers and the four operations: Calculating with whole numbers', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["−3", "4", "−9", "7"], "tip": "Number line."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["23", "35", "700", "14"], "tip": "Brackets, then ×÷."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["12 480", "4 992", "12480", "4992"], ["17 472", "17472"]], "tips": ["Split 14 into 10 + 4."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["39"]], "tips": ["Divide."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Yes", "No", "Yes", "Yes"], "tip": "Digit sums."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["50 × 20", "1000"], ["wrong", "too big", "10 times"], ["1008"]], "tips": ["Round both numbers."]}]}, "models": {"1": [["Q1", "−3; 4; −9; 7."]], "2": [["Q2", "23; 35; 700; 14."]], "3": [["Q3", "12 480 + 4 992 [1] = 17 472 [1]."], ["Q4", "39 [1]."]], "4": [["Q5", "4+2+3 = 9 yes; 5+1+4 = 10 no; even and 3+4+8 = 15 yes; 5³ yes."]], "5": [["Q6", "Estimate 50 × 20 = 1000 [1]; 10 080 is about 10 times too big [1]; correct answer 1008 [1]."]], "6": [["Exit ticket", "24."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "Calculate.", "Q3": "Calculate 1 248 × 14. Show your method.", "Q4": "936 passengers share 24 buses equally. How many per bus?", "Q5": "Divisible?", "Q6": "Juma says 48 × 21 = 10 080. Use an estimate to show he is wrong, then find the correct answer."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
