insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L3', 'Unit 3 Place value, ordering and rounding: Decimals to thousandths', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["4 tenths", "7 hundredths", "2 thousandths"], "tip": "Places after the point."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["23.45", "0.56", "4 200", "0.007"], "tip": "Move digits."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["4 + 0.8 + 0.02", "4+0.8+0.02"], ["4 + 0.7 + 0.12", "3 + 1.82", "4.8 + 0.02", "4 + 0.82", "2 + 2.82"]], "tips": ["Standard and regrouped."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["8", "3.5", "10", "0.6"], "tip": "Next digit."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["12.4, 12.405, 12.45", "12.4 12.405 12.45"], ["smallest", "least time", "hundredth", "compare digits"]], "tips": ["Compare place by place."]}]}, "models": {"1": [["Q1", "4 tenths; 7 hundredths; 2 thousandths."]], "2": [["Q2", "23.45; 0.56; 4200; 0.007."]], "3": [["Q3", "4 + 0.8 + 0.02 [1]; e.g. 4 + 0.7 + 0.12 [1]."]], "4": [["Q4", "8; 3.5; 10; 0.6."]], "5": [["Q5", "12.4, 12.405, 12.45 [1]: the smallest time is the fastest, comparing tenths then hundredths [1]."]], "6": [["Exit ticket", "4.7."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "What is the value of the underlined digit in 6.<u>4</u>72, 6.4<u>7</u>2, 6.47<u>2</u>?", "Q2": "Calculate.", "Q3": "Write 4.82 in two different ways by partitioning.", "Q4": "Round.", "Q5": "Three runners: 12.405 s, 12.45 s, 12.4 s. Order them fastest first and explain."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
