insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L4', 'Unit 4 Fractions, decimals and percentages: Working with fractions, decimals and percentages', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.75", "3½", "3/4", "24"], "tip": "Divide."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 1, "pts": [["0.3, 35%, 2/5", "0.3 35% 2/5"]], "tips": ["Change to percentages."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["7/12", "1⅕", "1/4", "5/8"], "tip": "Common denominators."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["15", "45", "6.35", "25.2"], "tip": "Build percentages from 1% or 10%."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["15"], ["45"]], "tips": ["25% = ¼."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["5/8", "2/8 + 3/8"], ["3/8"]], "tips": ["Add, then subtract from 1."]}]}, "models": {"1": [["Q1", "0.75; 3½; 3/4; 24."]], "2": [["Q2", "0.3 (30%), 35%, 2/5 (40%) [1]."]], "3": [["Q3", "7/12; 1⅕; 1/4; 5/8."]], "4": [["Q4", "15; 45; 6.35; 25.2."], ["Q5", "25% of 60 = $15 [1]; 60 − 15 = $45 [1]."]], "5": [["Q6", "1/4 + 3/8 = 5/8 eaten [1]; 3/8 left [1]."]], "6": [["Exit ticket", "60%."]]}, "labels": {"q2_0": "Q2", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "Order from smallest: 0.3, 2/5, 35%.", "Q3": "Calculate.", "Q4": "Calculate.", "Q5": "A $60 bag has 25% off. What is the sale price?", "Q6": "Amani eats 1/4 of a pizza and Baraka eats 3/8. What fraction is left?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
