insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L5', 'Unit 5 Ratio and proportion: Ratio and direct proportion', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["9", "15", "6"], "tip": "Multiply both parts."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["2 : 3", "1 : 4", "3 : 5"], "tip": "Divide by a common factor."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 1, "pts": [["12"]], "tips": ["× 3."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["2"], ["16"]], "tips": ["One pen first."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["2 : 3", "2:3"], ["2/5", "4/10", "40%", "0.4"]], "tips": ["Part : part, then part of whole."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["1.5", "1½"], ["15"]], "tips": ["One person."]}]}, "models": {"1": [["Q1", "9; 15; 6."]], "2": [["Q2", "2 : 3; 1 : 4; 3 : 5."]], "3": [["Q3", "$12 [1]."], ["Q4", "$2 each [1]; $16 [1]."]], "4": [["Q5", "Ratio 2 : 3 [1]; proportion 4/10 = 2/5 [1]."]], "5": [["Q6", "6 ÷ 4 = 1.5 per person [1]; 1.5 × 10 = 15 [1]."]], "6": [["Exit ticket", "2 : 3."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "How many red beads? (2 blue : 3 red)", "Q2": "Simplify.", "Q3": "5 mangoes cost $4. How much do 15 mangoes cost?", "Q4": "3 pens cost $6. Find the cost of 8 pens.", "Q5": "A bag has 4 green and 6 yellow sweets. Write the ratio of green to yellow in simplest form and the proportion that is green.", "Q6": "Juice for 4 people uses 6 oranges. How many oranges for 10 people?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
