insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L6', 'Unit 6 Time: Working with time', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["False", "True", "True", "False"], "tip": "60 minutes in an hour."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["2 h 15 min", "8 h 30 min", "1 h 6 min", "3 h 45 min"], "tip": "× 60."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["1.5 h", "2.2 h", "0.75 h", "4.25 h"], "tip": "÷ 60."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["15 min", "10:00", "3 h", "13:00"], ["3 h 35 min", "3 hours 35", "3h 35"]], "tips": ["Count on."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["4 h 18", "4 hours 18", "18"], ["0.3 × 60", "60", "not 100", "decimal"]], "tips": ["× 60."]}]}, "models": {"1": [["Q1", "False; true; true; false."]], "2": [["Q2", "As listed."]], "3": [["Q3", "As listed."]], "4": [["Q4", "09:45 → 10:00 is 15 min, 10:00 → 13:00 is 3 h, 13:00 → 13:20 is 20 min [1]; 3 h 35 min [1]."]], "5": [["Q5", "4 h 18 min [1]; 0.3 of an hour is 0.3 × 60 = 18 minutes, as an hour has 60 minutes, not 10 or 100 [1]."]], "6": [["Exit ticket", "30 minutes."]]}, "labels": {"q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false?", "Q2": "Convert.", "Q3": "Convert.", "Q4": "A train leaves at 09:45 and arrives at 13:20. How long is the journey in hours and minutes?", "Q5": "A calculator shows a journey took 4.3 hours. Write this in hours and minutes and explain why \"4 hours 3 minutes\" is wrong."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
