insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L7', 'Unit 7 Shapes and measures: Shapes, nets, area and volume', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Rhombus", "Trapezium", "Diameter", "Circumference"], "tip": "Properties."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["12 cm²", "20 cm²", "24 cm²"], "tip": "Half the rectangle."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Cube", "Triangular prism", "Square-based pyramid"], "tip": "Count the faces."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["60"], ["60 ml", "60"]], "tips": ["l × w × h; 1 cm³ = 1 ml."]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["4", "2 × 2"], ["24"]], "tips": ["6 faces."]}]}, "models": {"1": [["Q1", "Rhombus; trapezium; diameter; circumference."]], "2": [["Q2", "12; 20; 24 cm²."]], "3": [["Q3", "Cube; triangular prism; square-based pyramid."]], "4": [["Q4", "Volume 60 cm³ [1]; capacity 60 ml [1]."], ["Q5", "Each face 4 cm² [1]; 6 × 4 = 24 cm² [1]."]], "5": [["Q6", "Faces 12, 12, 8, 8, 6, 6 cm²: total 52 cm²."]], "6": [["Exit ticket", "6."]]}, "labels": {"q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name it.", "Q2": "Area of the right-angled triangle.", "Q3": "Which 3D shape does the net make?", "Q4": "A box is 5 cm long, 4 cm wide and 3 cm high. Find its volume and its capacity in ml.", "Q5": "A cube has edges of 2 cm. Find its surface area.", "Q6": "In your book, draw a net for a cuboid box 4 cm × 3 cm × 2 cm on squared paper. Label each face with its area and find the total surface area."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
