insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L8', 'Unit 8 Symmetry, angles and circles: Turns, angles and circles', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["4", "2", "3", "1"], "tip": "Count the matches."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Acute", "Right angle", "Obtuse", "Reflex"], "tip": "Compare with 90° and 180°."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["60°", "90°", "45°", "30°"], "tip": "180 minus the others."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["no", "more than 180", "over 180"]], "tips": ["Two obtuse angles add to more than…?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["wrong scale", "other scale", "inner", "outer"], ["140"]], "tips": ["180 − 40."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 1, "pts": [["5"]], "tips": ["Radius."]}]}, "models": {"1": [["Q1", "4; 2; 3; 1."]], "2": [["Q2", "Acute; right; obtuse; reflex."]], "3": [["Q3", "60; 90; 45; 30."], ["Q4", "No: two obtuse angles add to more than 180° [1]."]], "4": [["Q5", "She read the wrong scale on the protractor [1]; the angle is probably 140° [1]."], ["Q6", "5 cm [1]."]], "5": [["Q7", "e.g. a three-bladed pattern: order 3."]], "6": [["Exit ticket", "180°."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Order of rotational symmetry?", "Q2": "Type of angle?", "Q3": "Find the missing angle.", "Q4": "Can a triangle have two obtuse angles? Explain.", "Q5": "A student measures an obtuse angle and gets 40°. What mistake did she make and what is the likely correct angle?", "Q6": "To draw a circle with diameter 10 cm, how wide should you open your compasses?", "Q7": "In your book, use compasses to draw a circle of radius 4 cm. Inside it, design a logo with rotational symmetry of order 3 or 4. Write its order."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
