insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L9', 'Unit 9 Position and transformation: Coordinates and moving shapes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["1st", "2nd", "3rd", "4th"], "tip": "Signs of x and y."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 1, "pts": [["(−2, 5)", "(-2, 5)", "(-2,5)", "(−2,5)"]], "tips": ["Same sides."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["(4, 2)", "(−1, 4)", "(1, 7)", "(−2, 0)"], "tip": "x across, y up."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 2, "n": 2, "ans": ["(−3, 2)", "(3, −2)"], "tip": "Which coordinate changes sign?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["(2, −2)", "(2,-2)", "(2, -2)"], ["(2, 2)", "(2,2)"]], "tips": ["Translate, then reflect."]}]}, "models": {"1": [["Q1", "1st; 2nd; 3rd; 4th."]], "2": [["Q2", "(−2, 5) [1]."]], "3": [["Q3", "(4, 2); (−1, 4); (1, 7); (−2, 0)."]], "4": [["Q4", "(−3, 2); (3, −2)."], ["Q5", "The image has the same size and shape, turned a quarter turn."]], "5": [["Q6", "After the move: (2, −2) [1]; after the reflection: (2, 2) [1]."]], "6": [["Exit ticket", "The 3rd quadrant (bottom left)."]]}, "labels": {"q2_0": "Q2", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which quadrant? (1st top right, 2nd top left, 3rd bottom left, 4th bottom right)", "Q2": "Three corners of a square are (−2, 1), (2, 1) and (2, 5). Find the fourth.", "Q3": "Translate (1, 4).", "Q4": "Reflect (3, 2).", "Q5": "On squared paper, draw a right-angled triangle and rotate it 90° clockwise about one vertex. Shade the image.", "Q6": "A pirate starts at (−4, 3). He moves 6 right and 5 down, then reflects his position in the x-axis. Where does he end?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
