insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L10', 'Unit 10 Statistics: Investigating with data', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["?", "what time", "do", "which", "how"], ["predict", "think", "later", "earlier", "more", "most"]], "tips": ["Question then prediction."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Categorical", "Discrete", "Continuous", "Continuous"], "tip": "Words, counted or measured?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["4", "4", "5", "6"], "tip": "Order first."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["not supported", "wrong", "incorrect", "not correct"], ["14:00", "2 pm", "afternoon"]], "tips": ["Compare with the data."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["height"], ["jump", "distance", "measure"], ["scatter", "graph"]], "tips": ["Two measurements."]}]}, "models": {"1": [["Q1", "e.g. \"Do older students go to bed later?\" [1]; prediction: \"Older students go to bed later\" [1]."]], "2": [["Q2", "Categorical; discrete; continuous; continuous."]], "3": [["Q3", "Mode 4; median 4; mean 25 ÷ 5 = 5; range 6."]], "4": [["Q4", "Their prediction was not supported [1]; the temperature was highest at 14:00 [1]."]], "5": [["Q5", "Measure each student''s height [1] and the distance of their standing jump [1]; draw a scatter graph to see whether there is a pattern [1]."]], "6": [["Exit ticket", "7."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Write a question and a prediction for an investigation about students'' bedtimes.", "Q2": "Type of data?", "Q3": "For 2, 4, 4, 7, 8 find:", "Q4": "A class predicted the temperature would be highest at 12:00. Their line graph shows the highest temperature at 14:00. What should they conclude?", "Q5": "Plan an investigation to test whether taller students jump further. Include what you will measure and which graph you will draw."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
