insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS6-MATHS-L11', 'Unit 11 Probability: Chance and probability', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Impossible", "Even chance", "Certain", "Unlikely", "Likely"], "tip": "How likely?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Yes", "No", "Yes", "No"], "tip": "Can both happen?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["3/10", "7/10", "1/6", "1/2"], "tip": "Out of the total."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["4/20", "1/5", "0.2"], ["more", "trials", "flip more", "repeat"]], "tips": ["Results ÷ trials."]}]}, "models": {"1": [["Q1", "Impossible; even chance; certain; unlikely; likely."]], "2": [["Q2", "Yes; no; yes; no."]], "3": [["Q3", "3/10; 7/10; 1/6; 1/2."]], "4": [["Q4", "4/20 = 1/5 [1]; do many more trials [1]."]], "5": [["Q5", "Results are usually close to 15 but not exact: chance varies; more flips give results closer to half."]], "6": [["Exit ticket", "1/6."]]}, "labels": {"q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Choose the word.", "Q2": "Mutually exclusive?", "Q3": "Find the chance.", "Q4": "Amina flips a bottle 20 times and it lands upright 4 times. Estimate the chance of landing upright and say how she could get a better estimate.", "Q5": "Flip a coin 30 times and record the results in a tally chart. Compare your results with what you expected (15 heads). Explain any difference."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
